const res = $input.first().json.results[0];

return [
  {
    json: {
      lat_lon_z: {
        gps: `@${res.geometry.lat},${res.geometry.lng},14z`
      }
    }
  }
];

const rowToMatch = $input.first().json.row_number;

// ✅ Parse business_data properly
let business = $('If').first().json.business_data;

if (typeof business === "string") {
  try {
    business = JSON.parse(business);
  } catch {
    business = [];
  }
}

// Ensure array
if (!Array.isArray(business)) {
  business = [business];
}

let existingData = business;

// ✅ New data
let newData = $('Parser Code').first().json.result.data || [];

if (typeof newData === "string") {
  try {
    newData = JSON.parse(newData);
  } catch {
    newData = [];
  }
}

if (!Array.isArray(newData)) newData = [newData];

// 🔥 Dedup
const uniqueKeys = new Set(
  existingData.map(item => `${item.cid}_${item.fid}_${item.placeid}`)
);

const filteredNewData = newData.filter(item => {
  const key = `${item.cid}_${item.fid}_${item.placeid}`;
  if (uniqueKeys.has(key)) return false;
  uniqueKeys.add(key);
  return true;
});

const updatedData = [...existingData, ...filteredNewData];

return [
  {
    json: {
      row_number: rowToMatch,
      query: $input.first().json.query,
      location : $input.first().json.location,
      ll : $input.first().json.ll,
      hl : $input.first().json.hl,
      business_data: updatedData
    }
  }
];

// ── KEY FIX: Chunk reviews into groups of 10 to avoid Groq token limit ──
// Each chunk will be summarized separately, then a final meta-summary is produced.

const item = $input.first().json;
const search_params = item.searchParameters || {};
const allReviews = item.reviews || [];

// Grab business meta from the Loop Over Items current item
const placeItem = $('Loop Over Items').item.json;
const businessTitle = placeItem.title || 'Unknown Business';
const businessAddress = placeItem.address || '';
const businessRating = placeItem.rating || '';
const businessRatingCount = placeItem.rating_count || '';
const row_num = placeItem.row_number;

// Clean + cap reviews to 60 max to stay safe
const cleaned = allReviews
  .filter(r => r.snippet && r.snippet.trim() !== '')
  .slice(0, 60)
  .map(r => ({
    rating: r.rating,
    date: r.date,
    snippet: r.snippet.trim().slice(0, 300)  // cap each review snippet at 300 chars
  }));

// Chunk into groups of 10
const CHUNK_SIZE = 10;
const chunks = [];
for (let i = 0; i < cleaned.length; i += CHUNK_SIZE) {
  chunks.push(cleaned.slice(i, i + CHUNK_SIZE));
}

// Return one item per chunk — each will go through the LLM separately
if (chunks.length === 0) {
  // No reviews: return a placeholder so downstream doesn't break
  return [{
    json: {
      cid: search_params.cid,
      fid: search_params.fid,
      placeId: search_params.placeId || search_params.placeid,
      businessTitle,
      businessAddress,
      businessRating,
      businessRatingCount,
      row_num,
      chunkIndex: 0,
      totalChunks: 1,
      reviewChunk: JSON.stringify([]),
      noReviews: true
    }
  }];
}

return chunks.map((chunk, idx) => ({
  json: {
    cid: search_params.cid,
    fid: search_params.fid,
    placeId: search_params.placeId || search_params.placeid,
    businessTitle,
    businessAddress,
    businessRating,
    businessRatingCount,
    row_num,
    chunkIndex: idx,
    totalChunks: chunks.length,
    reviewChunk: JSON.stringify(chunk),
    noReviews: false
  }
}));

