// Collect all chunk summaries for this business and aggregate them
// This node runs after all chunks of one business are processed

const allItems = $input.all();

// Parse each chunk's LLM output
const allPros = [];
const allCons = [];
const allInsights = [];

let businessTitle = '';
let businessAddress = '';
let businessRating = '';
let businessRatingCount = '';
let cid = '';
let fid = '';
let placeId = '';
let row_num = null;

for (const item of allItems) {
  // The LLM output is in item.json.text
  const raw = item.json.text || item.json.output || '';
  businessTitle = item.json.businessTitle || businessTitle;
  businessAddress = item.json.businessAddress || businessAddress;
  businessRating = item.json.businessRating || businessRating;
  businessRatingCount = item.json.businessRatingCount || businessRatingCount;
  cid = item.json.cid || cid;
  fid = item.json.fid || fid;
  placeId = item.json.placeId || placeId;
  row_num = item.json.row_num ?? row_num;

  try {
    // Strip markdown fences if present
    const cleaned = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    if (Array.isArray(parsed.pros)) allPros.push(...parsed.pros);
    if (Array.isArray(parsed.cons)) allCons.push(...parsed.cons);
    if (Array.isArray(parsed.insights)) allInsights.push(...parsed.insights);
  } catch (e) {
    // If parsing fails, skip this chunk
  }
}

// Deduplicate by lowercased text
const dedup = arr => [...new Map(arr.map(x => [x.toLowerCase(), x])).values()];

return [{
  json: {
    cid,
    fid,
    placeId,
    businessTitle,
    businessAddress,
    businessRating,
    businessRatingCount,
    row_num,
    aggregated_pros: dedup(allPros).slice(0, 10),
    aggregated_cons: dedup(allCons).slice(0, 10),
    aggregated_insights: dedup(allInsights).slice(0, 6)
  }
}];

