// Parse final LLM output and prepare for sheet append
const item = $input.first().json;
const raw = item.text || item.output || '';
const row_num = $('aggregate_chunks').first().json.row_num

let parsed = {};
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    businessTitle: item.businessTitle,
    businessAddress: item.businessAddress,
    overallRating: item.businessRating,
    totalReviews: item.businessRatingCount,
    pros: item.aggregated_pros || [],
    cons: item.aggregated_cons || [],
    insights: item.aggregated_insights || [],
    summary: 'Summary parsing failed — raw LLM output stored.'
  };
}

const timestamp = new Date().toISOString();

return [{
  json: {
    timestamp,
    cid: item.cid || $('aggregate_chunks').first().json.cid,
    fid: item.fid || $('aggregate_chunks').first().json.fid,
    placeId: item.placeId || $('aggregate_chunks').first().json.placeId,
    row_num: row_num,
    businessTitle: parsed.businessTitle || item.businessTitle,
    businessAddress: parsed.businessAddress || item.businessAddress,
    overallRating: parsed.overallRating || item.businessRating,
    totalReviews: parsed.totalReviews || item.businessRatingCount,
    pros: JSON.stringify(parsed.pros || []),
    cons: JSON.stringify(parsed.cons || []),
    insights: JSON.stringify(parsed.insights || []),
    summary: parsed.summary || '',
    raw_llm_output: raw
  }
}];

// Check if this business already has a review summary cached
// by matching cid, fid, and placeId against the summary sheet rows

const currentItem = $('Loop Over Items').item.json;
const cid     = String(currentItem.cid     || '').trim();
const fid     = String(currentItem.fid     || '').trim();
const placeid = String(currentItem.placeid || '').trim();

// All rows from the summary sheet
const allRows = $input.all();

const alreadyExists = allRows.some(row => {
  const r = row.json;
  return (
    String(r.cid     || '').trim() === cid     &&
    String(r.fid     || '').trim() === fid     &&
    String(r.placeId || '').trim() === placeid
  );
});

return [{
  json: {
    ...currentItem,
    review_already_exists: alreadyExists
  }
}];

