let data = $input.first().json.business_data
let row_num = $input.first().json.row_number
// const limit  = $input.first().json.business_data.length

const limit  = 3 
if (typeof data === "string") {
  data = JSON.parse(data);
}

// Ensure it's an array
if (Array.isArray(data)) {
  // Sort by rating_count (highest first)
  data.sort((a, b) => (b.rating_count || 0) - (a.rating_count || 0));

  // Take top 3
  data = data.slice(0, limit);
}

return data.map(item => ({
  json: {
    ...item,
    row_number: row_num
  }
}));

// 🔹 1. Get old memory from Redis
let memory;

try {
  memory = JSON.parse($input.first().json.data || "{}");
} catch {
  memory = { history: [] };
}

// ensure history exists
if (!memory.history) {
  memory.history = [];
}

// 🔹 2. Get NEW data from Merge1
const newData = $('Merge1').first().json;

// 🔹 3. Create new entry
const newEntry = {
  timestamp: newData.timestamp || new Date().toISOString(),
  businessTitle: newData.businessTitle,
  businessAddress: newData.businessAddress,
  rating: Number(newData.overallRating),
  pros: typeof newData.pros === "string" ? JSON.parse(newData.pros) : newData.pros,
  cons: typeof newData.cons === "string" ? JSON.parse(newData.cons) : newData.cons,
  insights: typeof newData.insights === "string" ? JSON.parse(newData.insights) : newData.insights,
  summary: newData.summary,
  raw_llm_output: newData.raw_llm_output
};

// 🔹 4. Append
memory.history.push(newEntry);

// 🔹 5. Keep last 5
memory.history = memory.history.slice(-5);

// 🔹 6. Get query safely
const userQuery =$('Webhook').first().json.body.user_query|| "unknown";

const normalizedQuery = userQuery.toLowerCase().trim();

// 🔹 7. Return for Redis SET
return [{
  json: {
    key: `user_query:${normalizedQuery}`,
    value: JSON.stringify(memory)
  }
}];
